import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate that a quantity is a positive integer.
 * @param {unknown} qty
 * @returns {boolean}
 */
function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Validate that a discount percent is a number between 0 and 100.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Validate that payment terms are one of the accepted values.
 * @param {unknown} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return ['NET14', 'NET30', 'EOM'].includes(terms);
}

/**
 * Calculate the due date based on issue date and terms.
 * @param {string} issueDate - YYYY-MM-DD format
 * @param {string} terms - NET14, NET30, or EOM
 * @returns {string} - due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);

  // EOM: last day of the month of the issue date
  const [year, month] = issueDate.split('-').map(Number);
  const nextMonth = month === 12 ? 1 : month + 1;
  const nextYear = month === 12 ? year + 1 : year;
  const d = new Date(Date.UTC(nextYear, nextMonth - 1, 1));
  d.setUTCDate(d.getUTCDate() - 1);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!isValidTerms(terms)) return fail('TERMS_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const enrichedLines = [];
  for (const line of lines) {
    if (!isValidQty(line.qty)) return fail('QTY_INVALID');

    const discountPercent = 'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const dueDate = calculateDueDate(issueDate, terms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item (qty * unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(lineTotal(line) * discountPercent / 100);
}

/**
 * Calculate the VAT for a single line item (on the discounted amount).
 * @param {{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const discountedAmount = total - discount;
  return roundCents(discountedAmount * line.vatRate / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, voucher?: { code: string, amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<any> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} lineInput
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, lineInput) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const { sku, qty } = lineInput;
  if (!isValidQty(qty)) return fail('QTY_INVALID');

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const discount = 'discountPercent' in lineInput ? lineInput.discountPercent : TIER_DISCOUNTS[customer.tier];
  if (!isValidDiscount(discount)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<any> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<any> }} invoice
 * @param {Array<string>} existingNumbers - array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher (fixed amount discount) to a draft invoice.
 * @param {{ status: string, voucher?: any, lines: Array<any>, issueDate: string, customerId: string }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

